    <label>Status<select name="status" value={filters.status} onChange={e=>change({...filters,status:e.target.value,pagina:'1'})}><option value="">Todas</option><option value="nao-resolvidas">Não resolvidas</option><option value="erradas">Erradas</option><option value="comentadas">Com resolução comentada</option></select></label><label className="v2-filter-toggle"><input type="checkbox" name="comentadas" value="1" checked={!!filters.comentadas} onChange={e=>change({...filters,comentadas:e.target.checked?'1':'',pagina:'1'})}/>Somente com resolução comentada</label><label className="v2-filter-toggle"><input type="checkbox" name="erros" value="1" checked={!!filters.erros} onChange={e=>change({...filters,erros:e.target.checked?'1':'',pagina:'1'})}/>Caderno de erros e revisão</label><div className="v2-actions"><button type="submit" className="v2-button v2-primary">Buscar questões</button><button type="button" className="v2-button" onClick={()=>change(emptyFilters)}>Limpar filtros</button></div>
