    <ol className="v2-results">{results.slice((page-1)*30,page*30).map(q=><li key={q.id} className="v2-result"><article><p className="gb-eyebrow">{labels[q.banca]??q.banca} · {q.ano} · {labels[q.disciplina]??q.disciplina}</p><h2><Link href={`/questoes/${q.slug}`}>{q.tema}</Link></h2><p><SafeText text={q.enunciado.slice(0,220)}/>{q.enunciado.length>220?'…':''}</p><p className="mt-3 text-sm"><QualityBadge nivel={q.nivelQualidade as NivelQualidade}/> · {labels[q.assunto]??q.assunto}</p>{filters.erros&&errors[q.id]?.dueAt&&<p>Próxima revisão: {new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo'}).format(errors[q.id].dueAt)}</p>}</article></li>)}</ol>
    {!results.length&&<p className="v2-editorial">Nenhuma questão atende a essa combinação. Tente remover um filtro ou buscar outro termo.</p>}
    <nav className="v2-actions mt-6" aria-label="Páginas de resultados"><button type="button" className="v2-button" disabled={page<=1} onClick={()=>change({...filters,pagina:String(page-1)})}>Página anterior</button><button type="button" className="v2-button" disabled={page>=pages} onClick={()=>change({...filters,pagina:String(page+1)})}>Próxima página</button></nav></>;
