"use client";
import {SafeText} from "./safe-text";

import { useMemo, useState } from "react";
import Link from "next/link";
import { useSavedProgress } from "@/components/use-saved-progress";

import { enemDisplayNumber, hasEnemLanguages, selectEnemQuestions, type EnemLanguage } from "@/lib/enem-question-order";
type Question = { numero: number; texto: string; disciplina: string; habilidade: string; tema: string; obs?: string; pagina?: number; annulled?: boolean };

export function EnemExamReader({ id, title, questions, verified, pageCount }: { id: string; title: string; questions: Question[]; verified: boolean; pageCount?: number }) {
  const [pageOverride, setPageOverride] = useState<{question:number; page:number} | null>(null);
  const [index, setIndex] = useState(0);
  const [finished, setFinished] = useState(false);
  const [score, setScore] = useState<{ correct: number; incorrect: number; blank: number; annulled: number; items: { number: number; selected: string | null; key: string; status: "correct" | "incorrect" | "blank" | "annulled" }[] } | null>(null);
  const [grading, setGrading] = useState(false);
  const [error, setError] = useState("");
  const [language, setLanguage] = useState<EnemLanguage>("ingles");
  const [answers, setAnswers] = useState<Record<number, string>>({});
  const savedState = useMemo(() => ({ index, finished, score, language, answers }), [index, finished, score, language, answers]);
  const progress = useSavedProgress(`gabaru:prova:enem:${id}`, savedState, (s) => {
    const chosen = s.language === "espanhol" ? "espanhol" : "ingles";
    if (Number.isInteger(s.index) && s.index >= 0 && s.index < selectEnemQuestions(questions, chosen).length) setIndex(s.index);
    if (s.language === "ingles" || s.language === "espanhol") setLanguage(s.language);
    if (s.answers && typeof s.answers === "object") setAnswers(s.answers);
    setScore(s.score && Array.isArray(s.score.items) ? s.score : null);
    if (typeof s.finished === "boolean") setFinished(s.finished);
  }, {index:0,finished:false,score:null,language:"ingles",answers:{}});
  function restart() {
    if (!window.confirm("Apagar as respostas e recomeçar este caderno?")) return;
    setAnswers({}); setIndex(0); setPageOverride(null); setFinished(false); setScore(null); setError(""); progress.dismissResume();
  }
  const hasLanguages = hasEnemLanguages(questions);
  const orderedQuestions = selectEnemQuestions(questions, language);
  const question = orderedQuestions[index];
  if (!question) return <p className="gb-notice mt-8">Este caderno ainda não tem questões disponíveis.</p>;
  const displayedPage = pageOverride?.question === question.numero ? pageOverride.page : question.pagina;
  const reviewed = score?.items.find(item => item.number === question.numero);
  const marked = orderedQuestions.filter(q => answers[q.numero]).length;
  const needsReview = /apenas|incomplet|cortad|misturad|ileg[ií]vel|ausente|coluna|confund|errad|faltando|não aparece/i.test(question.obs ?? "");
  const related = id === "enem-2008" ? (question.numero === 1 ? [2] : question.numero === 23 ? [21, 22] : []) : [];
  async function finish() {
    if (!verified) { setFinished(true); return; }
    setGrading(true); setError("");
    try {
      const selectedAnswers = Object.fromEntries(orderedQuestions.filter(q => answers[q.numero]).map(q => [String(q.numero), answers[q.numero]]));
      const response = await fetch("/api/v1/enem-simulado", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ examId: id, language, answers: selectedAnswers }) });
      if (!response.ok) throw new Error("Falha ao corrigir");
      setScore(await response.json()); setFinished(true);
    } catch { setError("Não foi possível corrigir agora. Suas respostas continuam nesta página; tente novamente."); }
    finally { setGrading(false); }
  }
  return <section className="mt-8" aria-label="Caderno e respostas">
    {progress.resumed && <div className="gb-notice mb-4" role="status">Progresso encontrado neste navegador. <button type="button" className="underline font-semibold" onClick={progress.dismissResume}>Continuar de onde parei</button> · <button type="button" className="underline font-semibold" onClick={restart}>Recomeçar</button></div>}
    {!progress.storageAvailable && <p role="alert" className="gb-notice mb-4">Não foi possível salvar neste navegador. Mantenha a página aberta para preservar suas respostas.</p>}
    <div className="mb-6 flex items-center gap-3">{/* eslint-disable-next-line @next/next/no-img-element */}<img src="/marca/gabaru-carimbo.webp" width={48} height={48} alt="" className="rounded-full" /><div><p className="gb-eyebrow">SIMULADO GRATUITO</p><h2 className="gb-section-title">Sua prova do ENEM</h2></div></div>
    <p className="mb-6 text-n5">{pageCount ? "Leia o caderno e marque suas alternativas." : "Consulte o recorte original e marque suas alternativas."} As respostas ficam salvas neste navegador, quando disponível. {verified ? "Correção automática pelo gabarito oficial conferido." : "Gabarito em conferência: a correção automática ainda está em preparação."}</p>
    {hasLanguages && <fieldset className="mb-6" disabled={grading}><legend className="font-semibold">Escolha sua língua estrangeira</legend><div className="mt-2 flex gap-6">{(["ingles", "espanhol"] as const).map(l => <label key={l} className="flex items-center gap-2"><input type="radio" name="idioma" checked={language === l} onChange={() => { setLanguage(l); setIndex(0); setFinished(false); setScore(null); }} />{l === "ingles" ? "Inglês" : "Espanhol"}</label>)}</div><p className="mt-2 text-sm text-n5">As duas opções usam a numeração de 1 a 5 do caderno oficial. Só a língua escolhida entra na correção.</p></fieldset>}
    {finished ? <div className="gb-notice mb-8" role="status"><h3 className="text-xl font-bold">Simulado finalizado</h3>{!score && <p className="mt-3">{marked} de {orderedQuestions.length} questões respondidas · {orderedQuestions.length - marked} em branco.</p>}<p className="mt-3">{score ? <>{score.correct} acertos · {score.incorrect} erros · {score.blank} em branco · {score.annulled} anuladas. Questões anuladas aparecem separadamente. Resultado por acertos, não uma nota TRI.</> : <>O número de acertos e a nota TRI não estão disponíveis. Consulte o gabarito oficial para conferir suas respostas.</>}</p>{score && <details className="mt-5"><summary className="cursor-pointer font-semibold">Ver correção de cada questão</summary><ol className="mt-4 grid gap-3 sm:grid-cols-2">{score.items.map(item => <li key={item.number} className="rounded border border-n2 bg-white/60 p-3"><button type="button" className="font-semibold underline" onClick={() => { const i = orderedQuestions.findIndex(q => q.numero === item.number); if (i >= 0) { setIndex(i); setFinished(false); } }}>Questão {enemDisplayNumber(orderedQuestions.find(q => q.numero === item.number) ?? {numero:item.number, disciplina:""})}</button> · {item.status === "correct" ? "Acertou" : item.status === "incorrect" ? "Rever" : item.status === "annulled" ? "Anulada" : "Em branco"}<br />Sua resposta: {item.selected ?? "—"} · Gabarito: <strong>{item.key}</strong></li>)}</ol></details>}<div className="mt-4 flex flex-wrap gap-3"><button type="button" className="gb-button" onClick={() => setFinished(false)}>Revisar respostas</button><Link href="/provas/enem" className="gb-text-link">Escolher outra prova do ENEM →</Link><Link href="/treino" className="gb-text-link">Praticar mais questões →</Link><button type="button" className="gb-text-link" onClick={restart}>Recomeçar prova</button></div></div> :
    <fieldset disabled={grading} className="grid gap-8 lg:grid-cols-[minmax(0,1fr)_320px]">
      <div id="enem-caderno" className="min-w-0 scroll-mt-24">
        <a href="#enem-respostas" className="gb-text-link mb-3 inline-block lg:hidden">Ir para as respostas ↓</a>
        {needsReview && <p className="gb-notice mb-4">Este recorte está em revisão e pode não mostrar todo o conteúdo. <a className="underline" href={`https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos/${id.slice(5, 9)}`} target="_blank" rel="noopener noreferrer">Consulte o caderno oficial do Inep ↗</a></p>}
        {pageCount && displayedPage && <div className="mb-4 flex flex-wrap items-center gap-2">
          <button type="button" className="min-h-12 rounded border border-n2 px-3" disabled={displayedPage <= 1} onClick={() => setPageOverride({question:question.numero,page:displayedPage - 1})}>← Página anterior</button>
          <label>Página <select aria-label="Página do caderno" value={displayedPage} onChange={e => setPageOverride({question:question.numero,page:Number(e.currentTarget.value)})} className="min-h-12 rounded border border-n2 px-2">{Array.from({length:pageCount}, (_,i) => <option key={i} value={i+1}>{i+1}</option>)}</select> de {pageCount}</label>
          <button type="button" className="min-h-12 rounded border border-n2 px-3" disabled={displayedPage >= pageCount} onClick={() => setPageOverride({question:question.numero,page:displayedPage + 1})}>Próxima página →</button>
        </div>}
        <img src={displayedPage ? `/acervo/enem/${id}/${String(displayedPage).padStart(2,"0")}.webp` : `/questoes/${id}-q${String(question.numero).padStart(3, "0")}.webp`} alt={displayedPage ? `Página ${displayedPage} do caderno, ${title}` : `Recorte da questão ${enemDisplayNumber(question)}, ${title}`} className="h-auto w-full rounded-md border border-n2 bg-white" />
        {related.length > 0 && <details className="mt-4"><summary className="cursor-pointer py-3">Ver recortes relacionados</summary>{related.map(num => <img key={num} src={`/questoes/${id}-q${String(num).padStart(3,"0")}.webp`} alt={`Recorte da questão ${num}, ${title}`} className="mt-3 h-auto w-full rounded-md border border-n2" loading="lazy" />)}</details>}
        {question.texto && <details className="mt-4"><summary className="cursor-pointer py-3">Ler transcrição do enunciado</summary><p className="mb-3 text-sm">Texto auxiliar; confira figuras e alternativas no recorte original.</p><p className="whitespace-pre-wrap text-n5"><SafeText text={question.texto}/></p></details>}
      </div>
      <div id="enem-respostas" className="min-w-0 scroll-mt-24">
        <a href="#enem-caderno" className="gb-text-link mb-3 inline-block lg:hidden">↑ Voltar à questão</a>
        <h2 className="gb-section-title" aria-live="polite">Questão {enemDisplayNumber(question)}{question.annulled && <span className="ml-3 rounded border border-n2 bg-white px-2 py-1 align-middle text-sm">Anulada</span>}</h2>
        {question.annulled && <p className="mt-2 text-sm text-n5">Anulada no gabarito oficial. Não conta como acerto, erro ou questão em branco.</p>}
        <p className="mt-2 text-n5">{[question.disciplina, question.tema, question.habilidade].filter(Boolean).join(" · ")}</p>
        <p className="mt-2" role="status">{marked} de {orderedQuestions.length} itens marcados</p>
        {reviewed && <p className="gb-notice mt-4">Sua resposta: {reviewed.selected ?? "em branco"} · Gabarito oficial: <strong>{reviewed.key}</strong> · {reviewed.status === "incorrect" ? "Rever" : reviewed.status === "correct" ? "Correta" : reviewed.status === "annulled" ? "Anulada" : "Em branco"}.</p>}
        <fieldset className="my-5"><legend className="mb-3">Sua alternativa</legend><div className="grid grid-cols-5 gap-2">{["A", "B", "C", "D", "E"].map(a => <label key={a} className={`flex min-h-12 cursor-pointer items-center justify-center rounded border focus-within:ring-2 focus-within:ring-[#232323] ${answers[question.numero] === a ? "bg-[#232323] text-white" : "bg-white text-[#232323]"}`}><input className="sr-only" type="radio" name={`enem-q${question.numero}`} value={a} checked={answers[question.numero] === a} onChange={() => { setScore(null); setAnswers({ ...answers, [question.numero]: a }); }} />{a}</label>)}</div></fieldset>
        <button className="mb-5 text-sm underline" onClick={() => { if (window.confirm("Apagar a resposta desta questão?")) { setScore(null); setAnswers(({ [question.numero]: _removed, ...rest }) => rest); } }}>Limpar resposta</button>
        <div className="mb-5 flex gap-2"><button className="min-h-12 rounded border border-n2 px-3" disabled={index === 0} onClick={() => setIndex(index - 1)}>← Anterior</button><button className="min-h-12 rounded border border-n2 px-3" disabled={index === orderedQuestions.length - 1} onClick={() => setIndex(index + 1)}>Próxima →</button></div>
        <nav aria-label="Questões da prova" className="grid grid-cols-5 gap-2">{orderedQuestions.map((q, i) => <button key={q.numero} aria-label={`Questão ${enemDisplayNumber(q)}${q.annulled ? ", anulada" : ""}${answers[q.numero] ? ", respondida" : ""}`} aria-current={i === index ? "step" : undefined} onClick={() => setIndex(i)} className={`min-h-12 rounded border ${i === index ? "ring-2 ring-[#232323]" : ""} ${answers[q.numero] ? "bg-[#f2cdb4]" : "bg-white"}`}>{enemDisplayNumber(q)}</button>)}</nav>
        <button type="button" className="gb-button mt-6" disabled={grading || marked === 0} onClick={finish}>{grading ? "Corrigindo…" : "Finalizar simulado"}</button>{error && <p role="alert" className="mt-3 text-sm">{error}</p>} <button type="button" className="mt-6 min-h-12 rounded border border-n2 px-3" onClick={restart}>Recomeçar</button>
        <p className="mt-4 text-sm text-n5">Seu progresso fica neste navegador. Para preservar seus dados, não apague os dados do site.</p>
      </div>
    </fieldset>}
  </section>;
}

"use client";
import {useState} from "react";
import {ETEC_2026_2 as exam} from "@/data/etec-2026-2";
export function EtecAnswerSheet(){
 const [answers,setAnswers]=useState<Record<number,string>>({});const [done,setDone]=useState(false);
 const filled=Object.keys(answers).length;const correct=Object.entries(answers).filter(([n,a])=>exam.answerKey[Number(n)-1]===a).length;
 return <section className="mt-10" aria-labelledby="sheet-title"><h2 id="sheet-title" className="gb-section-title">Sua folha de respostas</h2><p className="mt-3 text-n5">Consulte o caderno oficial em outra aba, marque suas alternativas e confira ao terminar. Suas marcações ficam apenas nesta página e se perdem ao recarregar.</p>
 <p className="mt-5 font-semibold" role="status">{filled} de 50 respondidas</p>
 <div className="mt-5 grid gap-4 sm:grid-cols-2">{Array.from({length:50},(_,i)=>i+1).map(n=><fieldset className="rounded-md border border-n2 bg-white/60 p-4" key={n}><legend className="px-2 font-semibold">Questão {String(n).padStart(2,"0")}</legend><div className="grid grid-cols-5 gap-2">{['A','B','C','D','E'].map(letter=><label key={letter} className={`flex min-h-12 cursor-pointer items-center justify-center gap-1 rounded border px-1 ${answers[n]===letter?'border-ink bg-ink text-paper':'border-n2 bg-paper text-ink'}`}><input type="radio" name={`etec-${n}`} value={letter} checked={answers[n]===letter} disabled={done} onChange={()=>setAnswers(a=>({...a,[n]:letter}))} aria-label={`Questão ${n}, alternativa ${letter}`} /><span>{letter}</span></label>)}</div>{done&&<p className="mt-3 text-sm">{!answers[n]?'Não respondida':answers[n]===exam.answerKey[n-1]?'Acertou':'Rever'} · Gabarito oficial: <strong>{exam.answerKey[n-1]}</strong></p>}</fieldset>)}</div>
 {!done?<button className="gb-button mt-7" disabled={!filled} onClick={()=>setDone(true)}>Conferir {filled} respostas ↗</button>:<div className="gb-notice mt-7" role="status"><h3 className="text-xl font-semibold">{correct} acertos de 50 questões</h3><p className="mt-2">{filled-correct} respostas divergentes e {50-filled} não respondidas. Esta é uma conferência de estudo, não uma nota oficial ou classificação. Não aplica pontuação acrescida, critérios de desempate ou bonificações.</p><p className="mt-2">Resoluções comentadas ainda não estão disponíveis. Compare com o documento oficial, que prevalece em caso de retificação.</p><button className="gb-login mt-4" onClick={()=>{if(window.confirm("Apagar todas as respostas desta folha?")){setDone(false);setAnswers({})}}}>Limpar e tentar novamente</button></div>}
 </section>
}

"use client";
import {SafeText} from "./safe-text";
import {useState} from "react";
import Link from "next/link";
import {useMemo} from "react";
import {useSavedProgress} from "@/components/use-saved-progress";
import type {EtecReaderExam,EtecSummary,ReaderInstitution} from "@/lib/etec-types";
const LETTERS = ["A", "B", "C", "D", "E"] as const;

export function AcervoExamReader({exam,catalog,institution,alternativeCount=5}:{
 exam:EtecReaderExam;
 catalog:EtecSummary[];
 institution:ReaderInstitution;
 alternativeCount?:number;
}){
 const letters=LETTERS.slice(0,alternativeCount);
 const isEtec=institution==="etec";
 const count=exam.questions.length,valid=exam.questions.filter(q=>!q.annulled);
 const [number,setNumber]=useState(1),[page,setPage]=useState(exam.questions[0].page),[answers,setAnswers]=useState<Record<number,string>>({}),[answerKey,setAnswerKey]=useState<Record<number,string> | null>(null);
 const [pending,setPending]=useState(false),[error,setError]=useState("");
 const done=answerKey!==null;
 const savedState=useMemo(()=>({number,page,answers,answerKey}),[number,page,answers,answerKey]);
 const progress=useSavedProgress(`gabaru:prova:${institution}:${exam.id}`,savedState,(s)=>{
  if(Number.isInteger(s.number)&&s.number>=1&&s.number<=count)setNumber(s.number);
  if(exam.pages.some(p=>p.number===s.page))setPage(s.page);
  if(s.answers&&typeof s.answers==="object")setAnswers(s.answers);
  setAnswerKey(s.answerKey ?? null);
 },{number:1,page:exam.questions[0].page,answers:{},answerKey:null});
 const current=exam.pages.find(p=>p.number===page),question=exam.questions[number-1];
 const correctAnswer=answerKey?.[number];
 const score=valid.filter(q=>answerKey && answers[q.number]===answerKey[q.number]).length,filled=valid.filter(q=>answers[q.number]).length,annulled=count-valid.length;
 async function checkAnswers() {
  setPending(true);
  setError("");
  try {
   const response=await fetch("/api/v1/acervo/correcao", {
    method:"POST",
    headers:{"Content-Type":"application/json"},
    body:JSON.stringify({institution,edition:exam.id,answers}),
   });
   const data=await response.json() as {answerKey?:Record<number,string>;error?:string};
   if(!response.ok || !data.answerKey) throw new Error(data.error ?? "Não foi possível conferir a prova.");
   setAnswerKey(data.answerKey);
  } catch {
   setError("Não foi possível conferir a prova. Suas respostas foram mantidas. Tente novamente.");
  } finally {
   setPending(false);
  }
 }
 function reset() {
  if (pending || !window.confirm("Apagar as respostas e recomeçar esta prova?")) return;
  setAnswers({});
  setAnswerKey(null);
  setError("");
  select(1);
  progress.dismissResume();
 }
 function select(n:number){setNumber(n);if(exam.questions[n-1].pageMapped)setPage(exam.questions[n-1].page);}
 const pdf=`/acervo/${institution}/${exam.id}/prova.pdf#page=${page}`;
 return <section className="mt-8" aria-label="Caderno e respostas"><Link href={`/provas/${institution}`} className="gb-text-link">← Todas as {catalog.length} provas</Link>{progress.resumed&&<div className="gb-notice mt-4" role="status">Progresso encontrado neste navegador. <button type="button" className="underline font-semibold" onClick={progress.dismissResume}>Continuar de onde parei</button> · <button type="button" className="underline font-semibold" onClick={reset} disabled={pending}>Recomeçar</button></div>}{!progress.storageAvailable&&<p role="alert" className="gb-notice mt-4">Não foi possível salvar neste navegador. Mantenha a página aberta para preservar suas respostas.</p>}<details className="mt-4"><summary className="cursor-pointer py-3">Trocar de edição</summary><div className="mt-3 grid gap-2 sm:grid-cols-2">{catalog.map(e=><Link className="min-h-12 rounded border border-n2 p-3" key={e.id} href={`/provas/${institution}/${e.id}`} aria-current={e.id===exam.id?"page":undefined}>{e.title} · {e.count} questões</Link>)}</div></details>
 <p className="my-6 text-n5">Caderno integral: figuras, alternativas e textos compartilhados preservados. Consulte as páginas anteriores quando houver referência a um texto.</p>
 <div className="grid gap-8 lg:grid-cols-[minmax(0,1fr)_320px]"><div id="etec-caderno" className="scroll-mt-24"><a href="#etec-respostas" className="gb-text-link mb-4 inline-block py-2 lg:hidden">Ir para a folha de respostas ↓</a><div className="mb-3 flex flex-wrap items-center gap-3"><button className="min-h-12 rounded border border-n2 px-3" disabled={page<=exam.pages[0].number} onClick={()=>setPage(page-1)}>← Página anterior</button><label>Página <select aria-label="Página do caderno" className="min-h-12 rounded border border-n2 px-3" value={page} onChange={e=>setPage(Number(e.target.value))}>{exam.pages.map(p=><option key={p.number} value={p.number}>{p.number}</option>)}</select> de {exam.pageCount}</label><button className="min-h-12 rounded border border-n2 px-3" disabled={page>=exam.pages[exam.pages.length-1].number} onClick={()=>setPage(page+1)}>Próxima página →</button></div>
 {current?.image ? (
   <img src={current.image} alt={`Caderno oficial ${exam.title}, página ${page}.`} width={current.width ?? 988} height={current.height ?? 1278} className="h-auto w-full rounded-md border border-n2 bg-white" />
 ) : isEtec ? (
   <p role="status" className="gb-notice">Esta página está indisponível. Tente recarregar o caderno.</p>
 ) : (
   <>
     <iframe key={pdf} src={pdf} title={`Caderno oficial ${exam.title}, página ${page}`} className="h-[75vh] min-h-[480px] w-full rounded-md border border-n2 bg-white" loading="lazy" />
     <details className="mt-4 text-sm text-n5">
       <summary className="cursor-pointer py-2">O caderno não carregou?</summary>
       <a className="gb-text-link py-2" href={pdf} target="_blank" rel="noopener noreferrer">Abrir página do caderno em outra aba ↗</a>
     </details>
   </>
 )}
 {current?.text&&<details className="mt-4"><summary className="cursor-pointer py-3">Texto extraído desta página</summary><p className="mb-3 text-sm">Texto auxiliar: a extração pode alterar a ordem de leitura e não descreve figuras. Consulte a imagem do caderno para conferir.</p><pre className="whitespace-pre-wrap font-sans text-sm"><SafeText text={current.text}/></pre></details>}</div>
 <div id="etec-respostas" className="scroll-mt-24"><a href="#etec-caderno" className="gb-text-link mb-4 inline-block py-2 lg:hidden">↑ Voltar ao caderno</a><h2 className="gb-section-title" aria-live="polite" aria-atomic="true">Questão {number}</h2><p className="mt-2" role="status">{filled} de {valid.length} válidas respondidas</p>{!question.pageMapped&&<p className="gb-notice mt-3">A página desta questão não foi identificada automaticamente. Localize o número no caderno usando o seletor de páginas.</p>}
 {question.statement && (isEtec ? (
   <details className="mt-4">
     <summary className="cursor-pointer py-2 text-sm font-semibold">Ler transcrição da questão</summary>
     <p className="mt-2 leading-relaxed"><SafeText text={question.statement}/></p>
     {question.options && <ol className="mt-3 grid gap-2 text-sm">{letters.map(letter => <li key={letter}><strong>{letter}</strong> <SafeText text={question.options?.[letter]}/></li>)}</ol>}
   </details>
 ) : <div className="mt-5"><p className="leading-relaxed"><SafeText text={question.statement}/></p><p className="mt-2 text-sm text-n5">Texto auxiliar extraído do caderno oficial.</p></div>)}
 {question.annulled?<><p role="status" className="gb-notice my-5">Questão anulada no gabarito oficial. Separada dos acertos e erros. {isEtec?"Conta como ponto atribuído na soma bruta.":"Consulte o edital para os critérios de pontuação."}</p>{!isEtec&&question.options&&<ol className="my-5 grid gap-2">{letters.map(a=><li key={a} className="flex gap-3 rounded border border-n2 p-3"><strong>{a}</strong><span><SafeText text={question.options?.[a]}/></span></li>)}</ol>}</>:!isEtec&&question.options?<fieldset className="my-5"><legend className="mb-3">Sua alternativa</legend><div className="grid gap-2">{letters.map(a=><label key={a} className={`flex min-h-12 cursor-pointer items-start gap-3 rounded border border-n2 p-3 focus-within:ring-2 focus-within:ring-[#232323] ${done&&a===correctAnswer?'bg-[#f2cdb4] text-[#232323] ring-2 ring-[#c8501e]':answers[number]===a?'bg-[#232323] text-white':'bg-white text-[#232323]'}`}><input className="sr-only" type="radio" name={`q${number}`} value={a} checked={answers[number]===a} disabled={done||pending} onChange={()=>setAnswers({...answers,[number]:a})}/><strong>{a}</strong><span><SafeText text={question.options?.[a]}/></span></label>)}</div></fieldset>:<fieldset className="my-5"><legend className="mb-3">Sua alternativa</legend><div className="grid gap-2" style={{gridTemplateColumns:`repeat(${letters.length}, minmax(0, 1fr))`}}>{letters.map(a=><label key={a} className={`flex min-h-12 cursor-pointer items-center justify-center rounded border focus-within:ring-2 focus-within:ring-[#232323] ${done&&a===correctAnswer?'bg-[#f2cdb4] text-[#232323] ring-2 ring-[#c8501e]':answers[number]===a?'bg-[#232323] text-white':'bg-white text-[#232323]'}`}><input className="sr-only" type="radio" name={`q${number}`} value={a} checked={answers[number]===a} disabled={done||pending} onChange={()=>setAnswers({...answers,[number]:a})}/>{a}</label>)}</div></fieldset>}
 {done&&!question.annulled&&<p role="status" className="my-4 font-semibold">{answers[number]===correctAnswer?'Resposta correta.':'Gabarito oficial: '+correctAnswer+'.'}</p>}
 <div className="mb-5 flex gap-2"><button className="min-h-12 rounded border border-n2 px-3" disabled={number===1} onClick={()=>select(number-1)}>← Anterior</button><button className="min-h-12 rounded border border-n2 px-3" disabled={number===count} onClick={()=>select(number+1)}>Próxima →</button></div>
 <nav aria-label="Questões da prova" className="grid grid-cols-5 gap-2">{exam.questions.map(q=><button key={q.number} aria-label={`Questão ${q.number}${q.annulled?', anulada':answers[q.number]?', respondida':''}`} aria-current={q.number===number?'step':undefined} onClick={()=>select(q.number)} className={`min-h-12 rounded border ${q.number===number?'ring-2 ring-[#232323]':''} ${answers[q.number]?'bg-[#f2cdb4]':'bg-white'}`}>{q.number}{q.annulled?'*':''}</button>)}</nav>
 <button className="mt-6 min-h-12 w-full rounded bg-[#232323] px-4 text-white" onClick={checkAnswers} disabled={pending||done||!filled}>{pending?"Conferindo…":"Conferir respostas"}</button>{error&&<p role="alert" className="gb-notice mt-3">{error}</p>}{done&&<div role="status" className="my-4 font-semibold"><p>{score} acertos · {filled-score} erros · {valid.length-filled} em branco · {annulled} anuladas.</p>{isEtec ? <p>Soma bruta: {score+annulled} de {count} pontos, incluindo anuladas. Sem acréscimos, desempates ou classificação.</p> : <p>O resultado do treino informa acertos. Consulte o edital para saber como é calculada a classificação.</p>}</div>}
 {done&&<div className="gb-notice mt-4"><h3 className="font-semibold">Revise seus erros</h3><div className="mt-3 flex flex-wrap gap-2">{valid.filter(q=>answers[q.number]&&answers[q.number]!==answerKey?.[q.number]).map(q=><button type="button" className="rounded border border-n2 px-3 py-2 underline" key={q.number} onClick={()=>select(q.number)}>Questão {q.number}</button>)}</div><Link href="/provas" className="gb-text-link mt-4 inline-block">Escolher outra prova →</Link></div>}
 <button className="mt-3 min-h-12 rounded border border-n2 px-3" onClick={reset} disabled={pending}>Recomeçar</button><p className="mt-4 text-sm text-n5">Respostas salvas neste navegador quando disponível. Correção automática pelo gabarito conferido. Correção pelo gabarito oficial{exam.answerKeyRevised?', retificado':''}. Resoluções comentadas ainda não disponíveis.</p></div></div></section>;
}

