    {!caderno.correcao&&<p className="mt-4 gb-notice">Conferência manual: o gabarito oficial contém marcações em revisão. <a className="gb-text-link" href={`/acervo/${caderno.id}/gabarito.pdf`} target="_blank" rel="noopener noreferrer">Abrir gabarito no Gabaru ↗</a></p>}
