 <div className="grid gap-8 lg:grid-cols-[minmax(0,1fr)_320px]"><div><div className="mb-3 flex flex-wrap items-center gap-3"><button className="min-h-12 rounded border border-n2 px-3" disabled={page<=exam.pages[0].number} onClick={()=>setPage(page-1)}>← Página anterior</button><label>Página <select aria-label="Página do caderno" className="min-h-12 rounded border border-n2 px-3" value={page} onChange={e=>setPage(Number(e.target.value))}>{exam.pages.map(p=><option key={p.number} value={p.number}>{p.number}</option>)}</select> de {exam.pageCount}</label><button className="min-h-12 rounded border border-n2 px-3" disabled={page>=exam.pages[exam.pages.length-1].number} onClick={()=>setPage(page+1)}>Próxima página →</button></div>
