 <div><h2 className="gb-section-title" aria-live="polite" aria-atomic="true">Questão {number}</h2><p className="mt-2" role="status">{filled} de {valid.length} válidas respondidas</p>{!question.pageMapped&&<p className="gb-notice mt-3">A página desta questão não foi identificada automaticamente. Localize o número no caderno usando o seletor de páginas ou abra o PDF.</p>}
 {question.statement&&<div className="mt-5"><p className="leading-relaxed"><SafeText text={question.statement}/></p><p className="mt-2 text-sm text-n5">Texto extraído automaticamente do caderno oficial. Se divergir, vale o PDF.</p></div>}
 {question.answer==="ANULADA"?<><p role="status" className="gb-notice my-5">Questão anulada no gabarito oficial. Separada dos acertos e erros. Consulte o edital para os critérios de pontuação.</p>{question.options&&<ol className="my-5 grid gap-2">{LETTERS.map(a=><li key={a} className="flex gap-3 rounded border border-n2 p-3"><strong>{a}</strong><span><SafeText text={question.options?.[a]}/></span></li>)}</ol>}</>:question.options?<fieldset className="my-5"><legend className="mb-3">Sua alternativa</legend><div className="grid gap-2">{LETTERS.map(a=><label key={a} className={`flex min-h-12 cursor-pointer items-start gap-3 rounded border border-n2 p-3 focus-within:ring-2 focus-within:ring-[#232323] ${done&&a===question.answer?'bg-[#f2cdb4] text-[#232323] ring-2 ring-[#c8501e]':answers[number]===a?'bg-[#232323] text-white':'bg-white text-[#232323]'}`}><input className="sr-only" type="radio" name={`q${number}`} value={a} checked={answers[number]===a} disabled={done} onChange={()=>setAnswers({...answers,[number]:a})}/><strong>{a}</strong><span><SafeText text={question.options?.[a]}/></span></label>)}</div></fieldset>:<fieldset className="my-5"><legend className="mb-3">Sua alternativa</legend><div className="grid gap-2" style={{gridTemplateColumns:`repeat(${LETTERS.length},minmax(0,1fr))`}}>{LETTERS.map(a=><label key={a} className={`flex min-h-12 cursor-pointer items-center justify-center rounded border focus-within:ring-2 focus-within:ring-[#232323] ${answers[number]===a?'bg-[#232323] text-white':'bg-white text-[#232323]'}`}><input className="sr-only" type="radio" name={`q${number}`} value={a} checked={answers[number]===a} disabled={done} onChange={()=>setAnswers({...answers,[number]:a})}/>{a}</label>)}</div></fieldset>}
 {done&&question.answer!=="ANULADA"&&<p role="status" className="my-4 font-semibold">{answers[number]===question.answer?'Resposta correta.':'Gabarito oficial: '+question.answer+'.'}</p>}
 <div className="mb-5 flex gap-2"><button className="min-h-12 rounded border border-n2 px-3" disabled={number===1} onClick={()=>select(number-1)}>← Anterior</button><button className="min-h-12 rounded border border-n2 px-3" disabled={number===count} onClick={()=>select(number+1)}>Próxima →</button></div>
 <nav aria-label="Questões da prova" className="grid grid-cols-5 gap-2">{exam.questions.map(q=><button key={q.number} aria-label={`Questão ${q.number}${q.answer==='ANULADA'?', anulada':answers[q.number]?', respondida':''}`} aria-current={q.number===number?'step':undefined} onClick={()=>select(q.number)} className={`min-h-12 rounded border ${q.number===number?'ring-2 ring-[#232323]':''} ${answers[q.number]?'bg-[#f2cdb4]':'bg-white'}`}>{q.number}{q.answer==='ANULADA'?'*':''}</button>)}</nav>
 <button className="mt-6 min-h-12 w-full rounded bg-[#232323] px-4 text-white" onClick={()=>setDone(true)} disabled={done}>Conferir respostas</button>{done&&<div role="status" className="my-4 font-semibold"><p>{score} acertos · {filled-score} erros · {valid.length-filled} em branco · {annulled} anuladas.</p><p>Contagem de acertos, sem pesos. Não representa a classificação oficial, que é feita por curso, turno e câmpus, com os desempates do edital.</p></div>}
 {done&&<div className="gb-notice mt-4"><h3 className="font-semibold">Revise seus erros</h3><div className="mt-3 flex flex-wrap gap-2">{valid.filter(q=>answers[q.number]&&answers[q.number]!==q.answer).map(q=><button type="button" className="rounded border border-n2 px-3 py-2 underline" key={q.number} onClick={()=>select(q.number)}>Questão {q.number}</button>)}</div><Link href="/provas" className="gb-text-link mt-4 inline-block">Escolher outra prova →</Link></div>}
 <button className="mt-3 min-h-12 rounded border border-n2 px-3" onClick={()=>{if(window.confirm("Apagar as respostas e recomeçar esta prova?")){setDone(false);setAnswers({});select(1);progress.dismissResume();}}}>Recomeçar</button><p className="mt-4 text-sm text-n5">Respostas salvas neste navegador quando disponível. Correção automática pelo gabarito conferido. Correção pelo gabarito oficial{exam.answerKeyRevised?', definitivo após recursos':''}. Resoluções comentadas ainda não disponíveis.</p></div></div></section>;
}

