"use client";

import Link from "next/link";
import { useEffect, useRef, useState } from "react";

type Questao = {
  id: string;
  ano: number;
  dia: number | null;
  numero: number;
  disciplina: string;
  subtopico: string;
  habilidade: string;
  tema: string;
  img: string;
  w: number;
  h: number;
};

type Fase = "escolha" | "treino" | "fim";

const NOMES: Record<string, string> = {
  matematica: "Matemática",
  fisica: "Física",
  quimica: "Química",
  biologia: "Biologia",
  geografia: "Geografia",
  historia: "História",
  portugues: "Português",
  literatura: "Literatura",
  ingles: "Inglês",
  espanhol: "Espanhol",
  artes: "Artes",
  filosofia: "Filosofia",
  sociologia: "Sociologia",
  interdisciplinar: "Interdisciplinar",
};

const QUANTIDADES = [30, 60, 90];
const LETRAS = ["A", "B", "C", "D", "E"];

export function TreinoApp() {
  const [catalog, setCatalog] = useState<{
    disciplines: { slug: string; count: number }[];
    years: number[];
  } | null>(null);
  const [iniciando, setIniciando] = useState(false);
  const [ano, setAno] = useState("");
  const [banco, setBanco] = useState<Questao[] | null>(null);
  const [erro, setErro] = useState(false);
  const [fase, setFase] = useState<Fase>("escolha");
  const [quantidade, setQuantidade] = useState(30);
  const [disciplina, setDisciplina] = useState("todas");
  const [fila, setFila] = useState<Questao[]>([]);
  const [posicao, setPosicao] = useState(0);
  const [escolhida, setEscolhida] = useState<string | null>(null);
  const [confirmada, setConfirmada] = useState(false);
  const [respondidas, setRespondidas] = useState(0);
  // Gestão de foco: ao trocar de fase ou de questão, o botão que tinha o
  // foco sai do DOM e o foco se perderia no corpo da página. Levamos o
  // foco ao título da nova vista (h1 de cada fase), sem roubar o foco na
  // montagem inicial.
  const tituloRef = useRef<HTMLHeadingElement>(null);
  const montou = useRef(false);
  useEffect(() => {
    if (!montou.current) {
      montou.current = true;
      return;
    }
    tituloRef.current?.focus();
  }, [fase, posicao, erro]);

  useEffect(() => {
    const ctrl = new AbortController();
    const initial = new URLSearchParams(window.location.search).get(
      "disciplina",
    );
    queueMicrotask(() => { if (!ctrl.signal.aborted && initial) setDisciplina(initial); });
    const initialYear = new URLSearchParams(window.location.search).get("ano");
    queueMicrotask(() => { if (!ctrl.signal.aborted && initialYear && /^\d{4}$/.test(initialYear)) setAno(initialYear); });
    fetch("/api/v1/catalog", { signal: ctrl.signal })
      .then((r) => {
        if (!r.ok) throw new Error();
        return r.json();
      })
      .then((data) => {
        setCatalog(data);
        setBanco([]);
      })
      .catch((e) => {
        if (e.name !== "AbortError") setErro(true);
      });
    return () => ctrl.abort();
  }, []);
  const disciplinas = catalog?.disciplines.map((d) => d.slug) ?? [];
  const disponiveis =
    catalog?.disciplines
      .filter((d) => disciplina === "todas" || d.slug === disciplina)
      .reduce((n, d) => n + d.count, 0) ?? 0;
  async function comecar() {
    setIniciando(true);
    setErro(false);
    try {
      const query = new URLSearchParams({
        limit: String(quantidade),
        disciplina,
        random: "1",
      });
      if (ano) query.set("ano", ano);
      const res = await fetch(`/api/v1/questions?${query}`);
      if (!res.ok) throw new Error();
      const data = await res.json();
      if (!data.items.length) {
        setErro(true);
        return;
      }
      setFila(data.items);
      setPosicao(0);
      setEscolhida(null);
      setConfirmada(false);
      setRespondidas(0);
      setFase("treino");
    } catch {
      setErro(true);
    } finally {
      setIniciando(false);
    }
  }

  function confirmar() {
    if (!escolhida || confirmada) return;
    setConfirmada(true);
    setRespondidas((n) => n + 1);
  }

  function proxima() {
    if (posicao + 1 >= fila.length) {
      setFase("fim");
      return;
    }
    setPosicao((p) => p + 1);
    setEscolhida(null);
    setConfirmada(false);
  }

  if (erro) {
    return (
      <div className="rounded-2xl border border-n2 bg-white/70 p-8">
        <h1 ref={tituloRef} tabIndex={-1} className="text-2xl font-bold">
          Não foi possível carregar o treino.
        </h1>
        <p className="mt-3 text-n5">
          Não foi possível carregar as questões ou não há itens para esses
          filtros.
        </p>
        <button
          className="gb-button mt-5"
          onClick={() => {
            setErro(false);
            if (!catalog) window.location.reload();
          }}
        >
          Voltar e tentar novamente
        </button>
      </div>
    );
  }

  if (!banco) {
    return (
      <p className="font-mono text-sm text-n4" role="status">
        Carregando o banco de questões…
      </p>
    );
  }

  if (fase === "escolha") {
    return (
      <div>
        <p className="font-mono text-xs font-bold uppercase tracking-[0.14em] text-n4">
          Treino grátis
        </p>
        <h1 className="mt-3 text-4xl font-bold leading-tight tracking-tight sm:text-5xl">
          Treino do dia
        </h1>
        <p className="mt-4 text-lg text-n5">
          Escolha quantas questões quer fazer hoje e a disciplina. Sem cadastro
          para começar.
        </p>

        <div className="mt-10 rounded-2xl border border-n2 bg-white/70 p-6 sm:p-8">
          <fieldset>
            <legend className="font-semibold">Quantas questões hoje?</legend>
            <div className="mt-3 grid grid-cols-3 gap-3">
              {QUANTIDADES.map((q) => (
                <button
                  key={q}
                  type="button"
                  aria-pressed={quantidade === q}
                  onClick={() => setQuantidade(q)}
                  className={`min-h-14 rounded-xl border-2 font-mono text-lg font-bold transition ${
                    quantidade === q
                      ? "border-ink bg-ink text-paper"
                      : "border-n2 bg-paper text-ink hover:border-ink"
                  }`}
                >
                  {q}
                </button>
              ))}
            </div>
          </fieldset>

          <div className="mt-8">
            <label htmlFor="disciplina" className="font-semibold">
              Disciplina
            </label>
            <select
              id="disciplina"
              value={disciplina}
              onChange={(e) => setDisciplina(e.target.value)}
              className="mt-3 min-h-14 w-full rounded-xl border-2 border-n2 bg-paper px-4 text-lg focus:border-ink"
            >
              <option value="todas">Todas as disciplinas</option>
              {disciplinas.map((d) => (
                <option key={d} value={d}>
                  {NOMES[d] ?? d}
                </option>
              ))}
            </select>
            <p className="mt-2 text-sm text-n4">
              {disponiveis.toLocaleString("pt-BR")} questões nesta disciplina,
              somando todos os anos.
            </p>
          </div>

          <div className="mt-6">
            <label htmlFor="ano" className="font-semibold">
              Ano da prova
            </label>
            <select
              id="ano"
              value={ano}
              onChange={(e) => setAno(e.target.value)}
              className="mt-3 min-h-14 w-full rounded-xl border-2 border-n2 bg-paper px-4"
            >
              <option value="">Todos os anos</option>
              {catalog?.years.map((y) => (
                <option key={y} value={y}>
                  {y}
                </option>
              ))}
            </select>
          </div>
          <button
            type="button"
            onClick={comecar}
            disabled={disponiveis === 0 || iniciando}
            className="mt-8 inline-flex min-h-14 w-full items-center justify-center rounded-xl bg-gold-text px-6 text-lg font-bold text-white transition hover:-translate-y-0.5 hover:bg-[#a63f14] disabled:opacity-50"
          >
            {iniciando
              ? "Preparando treino…"
              : `Começar treino de até ${Math.min(quantidade, disponiveis)} questões`}
          </button>
        </div>

        <p className="mt-6 text-sm text-n4">
          A correção automática será ativada depois da integração e revisão dos
          gabaritos oficiais. Por enquanto, você seleciona respostas e conclui a
          sessão, sem correção ou explicações.
        </p>
      </div>
    );
  }

  if (fase === "fim") {
    return (
      <div className="text-center">
        <p className="font-mono text-xs font-bold uppercase tracking-[0.14em] text-n4">
          Treino concluído
        </p>
        <h1
          ref={tituloRef}
          tabIndex={-1}
          className="mt-3 text-4xl font-bold tracking-tight sm:text-5xl"
        >
          Você fez {respondidas} questões.
        </h1>
        <p className="mx-auto mt-4 max-w-md text-lg text-n5">
          Sua sessão foi concluída. O histórico e o plano individual ainda estão
          em desenvolvimento; as respostas desta sessão não são salvas.
        </p>
        <div className="mt-8 flex flex-col items-center gap-3 sm:flex-row sm:justify-center">
          <Link href="/" className="gb-button">
            Voltar ao início
          </Link>
          <button
            type="button"
            onClick={() => setFase("escolha")}
            className="inline-flex min-h-12 items-center rounded-md border border-ink px-6 font-semibold text-ink hover:bg-ink hover:text-paper"
          >
            Fazer outro treino
          </button>
        </div>
        <Link
          href="/planos"
          className="mt-6 inline-block text-sm font-semibold underline"
        >
          Ver os planos
        </Link>
      </div>
    );
  }

  const q = fila[posicao];
  const progresso = Math.round(
    ((posicao + (confirmada ? 1 : 0)) / fila.length) * 100,
  );
  const ultima = posicao + 1 >= fila.length;

  return (
    <div>
      <div className="flex items-center justify-between gap-4">
        <h1
          ref={tituloRef}
          tabIndex={-1}
          className="font-mono text-sm font-bold text-n5"
        >
          Questão {posicao + 1} de {fila.length}
        </h1>
        <button
          type="button"
          onClick={() => setFase("escolha")}
          className="text-sm font-semibold text-n5 underline"
        >
          Sair do treino
        </button>
      </div>
      <div
        className="mt-3 h-2 w-full overflow-hidden rounded-full bg-n1"
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={progresso}
        aria-label="Progresso do treino"
      >
        <div
          className="h-full rounded-full bg-ink transition-all"
          style={{ width: `${progresso}%` }}
        />
      </div>

      <article className="mt-6 overflow-hidden rounded-2xl border border-n2 bg-white/70 shadow-sm">
        <header className="flex flex-wrap items-center gap-2 border-b border-n2 px-5 py-4">
          <span className="rounded-md bg-ink px-2.5 py-1 font-mono text-xs font-bold uppercase text-paper">
            {NOMES[q.disciplina] ?? q.disciplina}
          </span>
          <span className="rounded-md border border-n3 px-2.5 py-1 font-mono text-xs font-bold text-n5">
            ENEM {q.ano}
            {q.dia ? ` · dia ${q.dia}` : ""}
          </span>
          <span className="rounded-md bg-gold-soft px-2.5 py-1 font-mono text-xs font-bold text-ink">
            {q.habilidade}
          </span>
        </header>

        <div className="bg-paper p-4 sm:p-6">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={q.img}
            width={q.w}
            height={q.h}
            alt={`Questão ${q.numero} do ENEM ${q.ano}`}
            className="mx-auto h-auto max-w-full"
          />
        </div>

        <div className="p-5 sm:p-6">
          <p className="text-sm text-n5">{q.tema}</p>
          <fieldset className="mt-4">
            <legend className="sr-only">Escolha uma alternativa</legend>
            <div className="grid grid-cols-5 gap-2 sm:gap-3">
              {LETRAS.map((l) => {
                const marcada = escolhida === l;
                return (
                  <button
                    key={l}
                    type="button"
                    aria-pressed={marcada}
                    disabled={confirmada}
                    onClick={() => setEscolhida(l)}
                    className={`min-h-14 rounded-xl border-2 font-mono text-lg font-bold transition disabled:cursor-not-allowed ${
                      marcada
                        ? "border-ink bg-ink text-paper"
                        : "border-n2 bg-paper text-ink hover:border-ink"
                    }`}
                  >
                    {l}
                  </button>
                );
              })}
            </div>
          </fieldset>

          {!confirmada ? (
            <button
              type="button"
              onClick={confirmar}
              disabled={!escolhida}
              className="mt-6 inline-flex min-h-14 w-full items-center justify-center rounded-xl bg-gold-text px-6 text-lg font-bold text-white transition hover:-translate-y-0.5 hover:bg-[#a63f14] disabled:opacity-50"
            >
              Confirmar resposta
            </button>
          ) : (
            <div className="mt-6 space-y-4">
              <p
                className="rounded-xl border border-n2 bg-paper p-4 text-n5"
                role="status"
              >
                Resposta registrada:{" "}
                <strong className="text-ink">{escolhida}</strong>. O gabarito
                oficial desta questão entra em breve.
              </p>
              <button
                type="button"
                onClick={proxima}
                className="inline-flex min-h-14 w-full items-center justify-center rounded-xl bg-ink px-6 text-lg font-bold text-paper transition hover:-translate-y-0.5"
              >
                {ultima ? "Ver resultado" : "Próxima questão"}
              </button>
            </div>
          )}
        </div>
      </article>
    </div>
  );
}

"use client";
import { useMemo, useState } from "react";
import { FolhaDeRespostas } from "@/components/folha-de-respostas";
import { useSavedProgress } from "@/components/use-saved-progress";

type Caderno = { id: string; titulo: string; paginas: number; inicio: number; alternativas: string[]; gabaritos: Record<string, string[] | undefined>; lingua_inicio?: number; lingua_fim?: number };
const idiomas: Record<string, string> = { portugues: "Português", ingles: "Inglês", espanhol: "Espanhol", frances: "Francês" };
export function UerjUelReader({ caderno }: { caderno: Caderno }) {
  const chaves = Object.keys(caderno.gabaritos);
  const [idioma, setIdioma] = useState(chaves.includes("ingles") ? "ingles" : chaves[0]);
  const [pagina, setPagina] = useState(caderno.inicio);
  const estado = useMemo(() => ({ idioma, pagina }), [idioma, pagina]);
  const progresso = useSavedProgress(`gabaru:leitor:${caderno.id}`, estado, salvo => {
    if (chaves.includes(salvo.idioma)) setIdioma(salvo.idioma);
    if (Number.isInteger(salvo.pagina) && salvo.pagina >= 1 && salvo.pagina <= caderno.paginas) setPagina(salvo.pagina);
  }, { idioma: chaves.includes("ingles") ? "ingles" : chaves[0], pagina: caderno.inicio });
  return <section className="mt-8" aria-label="Prova e folha de respostas">
    {progresso.resumed && <p className="gb-notice mb-4" role="status">Continuando da página salva neste navegador.</p>}
    {!progresso.storageAvailable && <p className="gb-notice mb-4" role="alert">Não foi possível salvar a posição neste navegador.</p>}
    {chaves.length > 1 && <label className="block font-semibold">Língua estrangeira para as questões {caderno.lingua_inicio ?? 23} a {caderno.lingua_fim ?? 27}<select className="mt-3 block min-h-12 w-full max-w-sm rounded border border-n2 bg-white px-4" value={idioma} onChange={e => setIdioma(e.target.value)}>{chaves.map(i => <option key={i} value={i}>{idiomas[i] ?? i}</option>)}</select><span className="mt-2 block text-sm font-normal text-n5">As respostas ficam salvas separadamente por idioma.</span></label>}
    <div className="mt-5 grid items-start gap-6 lg:grid-cols-[minmax(0,1fr)_360px]">
      <div id="caderno"><div className="mb-3 flex flex-wrap items-center gap-3"><button type="button" className="min-h-12 rounded border border-n2 px-3" disabled={pagina<=1} onClick={()=>setPagina(pagina-1)}>← Página anterior</button><span>Página {pagina} de {caderno.paginas}</span><button type="button" className="min-h-12 rounded border border-n2 px-3" disabled={pagina>=caderno.paginas} onClick={()=>setPagina(pagina+1)}>Próxima página →</button><a href="#folha" className="gb-text-link lg:hidden">Marcar respostas ↓</a></div>
        <label className="mb-4 flex items-center gap-3">Ir para a página<select className="min-h-12 rounded border border-n2 bg-white px-3" value={pagina} onChange={e=>setPagina(Number(e.target.value))}>{Array.from({length:caderno.paginas},(_,i)=><option key={i} value={i+1}>{i+1}</option>)}</select></label>
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={`/acervo/${caderno.id}/${String(pagina).padStart(2,"0")}.webp`} alt={`${caderno.titulo}, página ${pagina} do caderno`} className="h-auto w-full rounded-lg border border-n2 bg-white" />
        <p className="mt-3 text-sm text-n5">Consulte as páginas anteriores para textos e figuras compartilhados. A redação e as questões discursivas não são corrigidas automaticamente.</p>
      </div>
      <div id="folha" className="lg:sticky lg:top-4 lg:max-h-[90vh] lg:overflow-y-auto"><a href="#caderno" className="gb-text-link mb-3 inline-block lg:hidden">↑ Voltar ao caderno</a><FolhaDeRespostas key={`${caderno.id}-${idioma}`} id={`${caderno.id}-${idioma}`} titulo={caderno.titulo} sugeridas={60} alternativas={caderno.alternativas} gabarito={caderno.gabaritos[idioma]!} compacto /></div>
    </div>
  </section>;
}

'use client';
import {useCallback,useEffect,useState} from 'react';import {useAuth} from '@/context/auth-context';import {nextReview,progressKeys,type ProgressEntry} from '@/lib/study-progress';
type Ledger=Record<string,ProgressEntry>;
const flushingUsers=new Set<string>();
function read(key:string):Ledger{try{const value=JSON.parse(localStorage.getItem(key)??'{}');if(!value||typeof value!=='object'||Array.isArray(value))return {};return Object.fromEntries(Object.entries(value).filter(([,v])=>{const e=v as ProgressEntry;return e&&typeof e==='object'&&typeof e.questionId==='string'&&typeof e.attemptId==='string'&&/^[A-E]$/.test(e.selected)&&/^[A-E]$/.test(e.correctKey)&&typeof e.correct==='boolean'&&Number.isFinite(e.updatedAt)&&Number.isFinite(e.dueAt)&&Math.abs(e.dueAt)<=8640000000000000;})) as Ledger;}catch{return {};}}
export function useStudyProgress(){const {user}=useAuth(),uid=user?.uid;const [progress,setProgress]=useState<Ledger>({}),[errors,setErrors]=useState<Ledger>({}),[syncError,setSyncError]=useState(false);
 const restore=useCallback(()=>{const keys=progressKeys(uid);setProgress(read(keys.progress));setErrors(read(keys.errors));},[uid]);
 const flush=useCallback(async()=>{if(!user||flushingUsers.has(user.uid))return;flushingUsers.add(user.uid);const keys=progressKeys(user.uid);try{for(let count=0;count<100;count++){const next=Object.entries(read(keys.pending))[0];if(!next)break;const [id,entry]=next;const response=await fetch('/api/v1/study',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${await user.getIdToken()}`},body:JSON.stringify({attemptId:entry.attemptId,questionId:entry.questionId,selected:entry.selected})});if(!response.ok)throw Error('sync');const server=await response.json() as ProgressEntry;const all=read(keys.progress),mistakes=read(keys.errors);if(all[entry.questionId]?.attemptId===entry.attemptId){all[entry.questionId]=server;if(server.hadError)mistakes[entry.questionId]=server;localStorage.setItem(keys.progress,JSON.stringify(all));localStorage.setItem(keys.errors,JSON.stringify(mistakes));}const current=read(keys.pending);delete current[id];localStorage.setItem(keys.pending,JSON.stringify(current));}setSyncError(false);window.dispatchEvent(new Event('gabaru-progresso'));}catch{setSyncError(true);}finally{flushingUsers.delete(user.uid);}},[user]);
 useEffect(()=>{let cancelled=false;queueMicrotask(()=>{if(!cancelled)restore();});window.addEventListener('storage',restore);window.addEventListener('gabaru-progresso',restore);window.addEventListener('online',flush);
 if(user){(async()=>{try{let cursor:string|null=null;for(let page=0;page<40;page++){const response=await fetch('/api/v1/study'+(cursor?'?cursor='+encodeURIComponent(cursor):''),{headers:{Authorization:`Bearer ${await user.getIdToken()}`}});if(!response.ok)throw Error('sync');const data=await response.json() as {items:ProgressEntry[];nextCursor:string|null};if(cancelled)return;const keys=progressKeys(user.uid),local=read(keys.progress),mistakes=read(keys.errors);for(const entry of data.items){if(!local[entry.questionId]||entry.updatedAt>local[entry.questionId].updatedAt)local[entry.questionId]=entry;if(entry.hadError||!entry.correct||mistakes[entry.questionId])mistakes[entry.questionId]=entry;}localStorage.setItem(keys.progress,JSON.stringify(local));localStorage.setItem(keys.errors,JSON.stringify(mistakes));cursor=data.nextCursor;if(!cursor)break;}restore();await flush();}catch{if(!cancelled)setSyncError(true);}})();}
 return()=>{cancelled=true;window.removeEventListener('storage',restore);window.removeEventListener('gabaru-progresso',restore);window.removeEventListener('online',flush);};},[user,restore,flush]);
 const record=useCallback((input:{questionId:string;selected:string;correctKey:string;attemptId:string})=>{try{const keys=progressKeys(uid),all=read(keys.progress);if(all[input.questionId]?.attemptId===input.attemptId)return;const entry=nextReview(all[input.questionId],input);all[input.questionId]=entry;const mistakes=read(keys.errors);if(entry.hadError||!entry.correct||mistakes[input.questionId])mistakes[input.questionId]=entry;localStorage.setItem(keys.progress,JSON.stringify(all));localStorage.setItem(keys.errors,JSON.stringify(mistakes));if(user){const pending=read(keys.pending);pending[input.attemptId+'_'+input.questionId]=entry;localStorage.setItem(keys.pending,JSON.stringify(pending));void flush();}window.dispatchEvent(new Event('gabaru-progresso'));}catch{setSyncError(true);}},[uid,user,flush]);
 return {user,progress,errors,record,syncError,retry:flush};
}

import Link from "next/link";
import { ARCHIVES, ARCHIVE_INFO, archiveYears, applicationName, type Institution } from "@/lib/vestibular-archive";

export function VestibularArchivePage({ institution }: { institution: Institution }) {
