import "server-only";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import bank from "@/data/treino-banco.json";
import verifiedExams from "@/data/enem-gabaritos-conferidos.json";
import exams from "@/data/enem-exams.json";
import paginatedExams from "@/data/enem-cadernos-paginados.json";

export const ENEM_SOURCE = "https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos";
export const ENEM_YEARS = Array.from({ length: 28 }, (_, i) => 2025 - i);
function applicationOrder(id: string) {
  if (id === "enem-2025-d2" || id.includes("-belem-")) return 1;
  if (["enem-2021-d2", "enem-2022-d2"].includes(id)) return 1;
  if (id === "enem-2020-d2" || id.includes("-digital-")) return 2;
  if (id.includes("-ppl-") || id.includes("-reaplicacao-")) return 3;
  return 0;
}

export const enemExams = [...exams.filter(exam => !paginatedExams.some(entry => entry.id === exam.id)), ...paginatedExams.map(({id, year, day, total, description, disciplines}) => ({
  id, year, day, total, description, disciplines,
}))].sort((left, right) => right.year - left.year || applicationOrder(left.id) - applicationOrder(right.id) || (left.day ?? 0) - (right.day ?? 0));
type Item = { numero: number; texto: string; disciplina: string; habilidade: string; tema: string; obs?: string; pagina?: number; annulled?: boolean };
export function readEnemExam(id: string) {
  const paginated = paginatedExams.find(entry => entry.id === id);
  if (paginated) {
    const questions: Item[] = paginated.questions.map(({numero,pagina,gabarito,disciplina}: {numero: number; pagina: number; gabarito: string; disciplina?: string}) => ({
      numero, pagina, annulled:gabarito === "ANULADA", texto:"", disciplina:disciplina ?? (numero < 136 ? "Ciências da Natureza" : "Matemática"), habilidade:"", tema:"",
    }));
    return { id, year:paginated.year, day:paginated.day, total:paginated.total,
      description:paginated.description, disciplines:paginated.disciplines, pageCount:paginated.pageCount, questions };
  }
  const exam = exams.find(e => e.id === id);
  if (!exam) return null;
  const data = JSON.parse(readFileSync(join(process.cwd(), "content", "enem", id, "dados.json"), "utf8")) as { questoes: Item[] };
  const annulled = new Set(verifiedExams.some(entry => entry.id === id)
    ? bank.filter(q => q.id.startsWith(id + "-q") && q.gabarito === "ANULADA").map(q => q.numero)
    : []);
  return { ...exam, pageCount: undefined, questions: data.questoes.map(q => ({ ...q, annulled: annulled.has(q.numero) })) };
}
export function enemTitle(exam: (typeof exams)[number]) {
  const application = exam.id === "enem-2025-d2" ? "Aplicação Belém / Ananindeua / Marituba" : exam.id.includes("-ppl-") ? "Reaplicação / PPL" : exam.id === "enem-2020-d2" ? "Digital" : "Regular";
  const paginated = paginatedExams.find(entry => entry.id === exam.id);
  if (paginated) return `ENEM ${exam.year} · ${exam.day}º dia · ${paginated.description}`;
  if (exam.id === "enem-2021-d2") return "ENEM 2021 · 2º dia · Caderno 5 Amarelo (superampliado)";
  if (exam.id === "enem-2022-d2") return "ENEM 2022 · 2º dia · Caderno 6 Cinza (ampliado)";
  return `ENEM ${exam.year} · ${application} · ${exam.day ? exam.day + "º dia" : "Prova única"}`;
}

/**
 * Forma PÚBLICA de uma edição do acervo (resposta de /api/v1/etec e
 * /api/v1/coluni quando `?edition=` é indicado).
 *
 * A seleção pública nunca devolve o gabarito (`answer`) de cada questão —
 * a mesma regra estrutural do repositório Postgres e da seleção do ENEM.
 * Em troca, cada questão expõe `annulled` (derivado no servidor de
 * `answer === "ANULADA"`): saber que uma questão foi anulada é informação
 * pública da prova; a letra do gabarito, não.
 *
 * Também remove o `text` das páginas (transcrição interna de trabalho);
 * o resto da proveniência (URLs e hashes oficiais) é público por desenho —
 * é a base do Selo de Questão Oficial Verificada.
 */
interface ExamQuestionLike {
  answer?: string;
  [key: string]: unknown;
}

interface ExamPageLike {
  text?: string;
  [key: string]: unknown;
}

export interface ExamLike {
  questions: ExamQuestionLike[];
  pages: ExamPageLike[];
  [key: string]: unknown;
}

export function toPublicExamDetail<T extends ExamLike>(exam: T) {
  return {
    ...exam,
    pages: exam.pages.map(({ text: _text, ...page }) => page),
    questions: exam.questions.map(({ answer, ...question }) => ({
      ...question,
      annulled: answer === "ANULADA",
    })),
  };
}

import "server-only";

import { existsSync } from "node:fs";
import { join } from "node:path";
import { toReaderExam, type EtecExam, type ReaderInstitution } from "./etec-types";

export function toPaginatedReaderExam(exam: EtecExam, institution: ReaderInstitution) {
  const reader = toReaderExam(exam);
  const pages = new Map(reader.pages.map(page => [page.number, page]));
  for (let number = 1; number <= exam.pageCount; number++) {
    const page = pages.get(number);
    if (page?.image) continue;
    const image = `/acervo/${institution}/${exam.id}/pagina-${String(number).padStart(2, "0")}.webp`;
    if (existsSync(join(process.cwd(), "public", image))) {
      pages.set(number, { number, image, text: page?.text ?? "" });
    }
  }
  return { ...reader, pages: Array.from(pages.values()).sort((a, b) => a.number - b.number) };
}

import "server-only";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { toPublicQuestion } from "./questions-public";
export type Question = {
  id: string;
  ano: number;
  dia: number | null;
  numero: number;
  disciplina: string;
  subtopico: string;
  habilidade: string;
  tema: string;
  img: string;
  w: number;
  h: number;
  // Gabarito oficial (INEP) casado por caderno/número; null enquanto a
  // edição não tiver casamento provado (ex.: 2000–2008). "ANULADA" quando
  // o gabarito oficial marca a questão como anulada.
  gabarito: "A" | "B" | "C" | "D" | "E" | "ANULADA" | null;
};
export type AnswerStatus = "available" | "partial" | "pending";
function statusFor(qs: Question[]): AnswerStatus {
  if (qs.length > 0 && qs.every((q) => q.gabarito)) return "available";
  if (qs.some((q) => q.gabarito)) return "partial";
  return "pending";
}
// O banco vive FORA de public/ de propósito: contém os gabaritos oficiais
// e nunca pode ser servido como ficheiro estático. Só o servidor o lê;
// a API pública filtra o gabarito via questions-public.ts.
const bank = JSON.parse(
  readFileSync(join(process.cwd(), "src/data/treino-banco.json"), "utf8"),
) as Question[];
export const questionCatalog = {
  total: bank.length,
  institutions: ["enem"],
  years: [...new Set(bank.map((q) => q.ano))].sort((a, b) => b - a),
  disciplines: [...new Set(bank.map((q) => q.disciplina))]
    .sort()
    .map((slug) => ({
      slug,
      count: bank.filter((q) => q.disciplina === slug).length,
    })),
  answerStatus: statusFor(bank),
  difficultyStatus: "not-calibrated" as const,
};
export function selectQuestions(params: URLSearchParams) {
  const discipline = params.get("disciplina"),
    year = params.get("ano"),
    institution = params.get("instituicao");
  const limit = Number(params.get("limit") ?? 30),
    offset = Number(params.get("offset") ?? 0);
  if (
    !Number.isInteger(limit) ||
    limit < 1 ||
    limit > 90 ||
    !Number.isInteger(offset) ||
    offset < 0 ||
    (year && !/^\d{4}$/.test(year))
  )
    throw new Error(
      "Filtros inválidos. Use limit de 1 a 90, offset não negativo e ano com quatro dígitos.",
    );
  let pool = bank.filter(
    (q) =>
      (!discipline || discipline === "todas" || q.disciplina === discipline) &&
      (!year || q.ano === Number(year)) &&
      (!institution || institution === "enem"),
  );
  if (params.has("dificuldade")) pool = []; // no inferred difficulty presented as measured
  if (params.get("random") === "1") {
    pool = [...pool];
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
  }
  return {
    version: 1,
    total: pool.length,
    offset,
    limit,
    nextOffset: offset + limit < pool.length ? offset + limit : null,
    answerStatus: statusFor(pool),
    // Seleção pública: o gabarito NUNCA sai nos itens (ver questions-public.ts).
    // O `answerStatus` agregado continua público — diz SE há gabarito, não QUAL.
    items: pool.slice(offset, offset + limit).map(toPublicQuestion),
  };
}

